#[test]fn local_socket_loss_retains_world_without_refreshing_inspection_or_play(){tauri::async_runtime::block_on(async{
 let(mut c,record,_,_)=fixture();let app=*uuid::Uuid::new_v4().as_bytes();let native=*uuid::Uuid::new_v4().as_bytes();let peer=nt2_local_ws::server::Peer{app,native,generation:1};let id=crate::local_owner::connected(peer,&std::env::current_exe().unwrap()).unwrap();let owner=(id,[1;16]);c.world.native=Some(owner);c.game.as_mut().unwrap().owner=owner;let ticket=c.world.coordinator.bind(record.world,owner,record.sequence);
 {let mut slot=c.pending.lock().unwrap();let p=slot.as_mut().unwrap();p.owner=Some(owner);p.release=true;p.last_seen=Some(Instant::now()-Duration::from_secs(30));p.collection_until=Some(Instant::now()+Duration::from_secs(6));}
 let original=c.pending.lock().unwrap().as_ref().unwrap().observation.clone().unwrap();crate::local_owner::disconnected(peer);c.lc1_native().await.unwrap();let held=c.pending.lock().unwrap().clone().unwrap();assert_eq!(c.world.native,Some(owner));assert_eq!(c.world.coordinator.ticket.as_ref(),Some(&ticket));assert!(!held.release&&held.authority_until<=Instant::now()&&held.collection_until.is_none());assert_eq!(held.observation.as_ref().unwrap().observed_at,original.observed_at);assert!(held.transport_observation_floor>=original.sequence);
 let next=nt2_local_ws::server::Peer{generation:2,..peer};assert_eq!(crate::local_owner::connected(next,&std::env::current_exe().unwrap()).unwrap(),id);c.lc1_native().await.unwrap();let collecting=c.pending.lock().unwrap().clone().unwrap();assert_eq!(c.world.native,Some(owner));assert!(!collecting.release);assert!(collecting.collection_until.is_some_and(|t|t>Instant::now()));assert_eq!(collecting.observation.as_ref().unwrap().observed_at,original.observed_at);assert_eq!(collecting.last_seen,held.last_seen);c.lc1_reconcile().unwrap();assert!(c.world.network.is_none(),"Socket reauthentication reused pre-outage engine evidence");crate::local_owner::disconnected(next);crate::local_owner::retire_app(app);
});}
#[test]fn retained_socket_marker_opens_collection_without_admitting_cached_inspection(){tauri::async_runtime::block_on(async{
 let(mut c,record,report,_)=fixture();let peer=nt2_local_ws::server::Peer{app:*uuid::Uuid::new_v4().as_bytes(),native:*uuid::Uuid::new_v4().as_bytes(),generation:1};let id=crate::local_owner::connected(peer,&std::env::current_exe().unwrap()).unwrap();let owner=(id,[1;16]);c.world.native=None;c.world.chosen=true;c.game=None;*c.pending.lock().unwrap()=None;{let mut d=c.native_diagnostics.lock().unwrap();d.rejoin=Default::default();let mut wrong=record.marker().unwrap();wrong.bundle_digest="c".repeat(64);d.rejoin.world_offered=Some((id,wrong));d.rejoin.world_context=Some(owner.1);}
 c.lc1_native().await.unwrap();assert!(c.world.native.is_none()&&c.pending.lock().unwrap().is_none(),"Changed saved marker became an active conversation");c.native_diagnostics.lock().unwrap().rejoin.world_offered=Some((id,record.marker().unwrap()));c.lc1_native().await.unwrap();assert_eq!(c.world.native,Some(owner));{let slot=c.pending.lock().unwrap();let p=slot.as_ref().unwrap();assert!(p.local_rebind&&!p.loaded&&!p.release&&p.observation.is_none());}
 let mut sample=report;sample.context=owner.1;sample.sequence=100;sample.observed_at=Instant::now();sample.observation.protected=true;{c.pending.lock().unwrap().as_mut().unwrap().observation=Some(sample.clone());}c.lc1_native().await.unwrap();let p=c.pending.lock().unwrap().clone().unwrap();assert!(!p.local_rebind&&p.loaded&&!p.release);assert_eq!(p.transport_observation_floor,100);assert_eq!(p.invalidated_observation,0,"Transport freshness invalidated frozen content");assert_eq!(p.observation.as_ref().unwrap().observed_at,sample.observed_at);c.lc1_reconcile().unwrap();assert!(c.world.network.is_none(),"Retained original inspection was treated as a fresh post-rebind observation");crate::local_owner::disconnected(peer);crate::local_owner::retire_app(peer.app);
});}
#[test]fn local_socket_rejected_seed_keeps_specific_reason_without_network_or_play(){tauri::async_runtime::block_on(async{
 let(mut c,record,_,_)=fixture();let peer=nt2_local_ws::server::Peer{app:*uuid::Uuid::new_v4().as_bytes(),native:*uuid::Uuid::new_v4().as_bytes(),generation:1};let id=crate::local_owner::connected(peer,&std::env::current_exe().unwrap()).unwrap();let owner=(id,[1;16]);c.world.native=Some(owner);c.world.coordinator.bind(record.world,owner,record.sequence);c.world.next=None;
 {let mut slot=c.pending.lock().unwrap();let p=slot.as_mut().unwrap();p.owner=Some(owner);p.release=false;p.last_seen=Some(Instant::now());p.generation=Some((c.generation.clone(),c.generation.load(Ordering::Acquire)));let r=p.observation.as_mut().unwrap();r.context=owner.1;r.observation.actual_seed=Some("999".into());r.observed_at=Instant::now();r.sequence=100;p.invalidated_observation=r.sequence;}
 for _ in 0..3{assert_eq!(c.lc1_reconcile().unwrap_err(),"Loaded seed differs from stable world");assert!(c.world.network.is_none());let mut slot=c.pending.lock().unwrap();let p=slot.as_mut().unwrap();assert!(!p.release);let r=p.observation.as_mut().unwrap();r.sequence+=1;p.invalidated_observation=r.sequence;}
 crate::local_owner::disconnected(peer);crate::local_owner::retire_app(peer.app);
});}
